-- 00370 — لوحة المساحة في بوابة التطوير المركزية + استرداد المساحة تلقائياً (ضغط ليلي)
--  • space_settings: حدود الخطة (قاعدة البيانات / التخزين) — افتراضي الخطة المجانية (500 MB / 1 GB)، Pro بزر واحد (8 GB / 100 GB)، أو مخصص.
--  • space_overview(): حجم القاعدة والمتبقي والقابل للاسترداد، التخزين لكل حاوية، أكبر الجداول ونسبة الشطب فيها، تنبيهات 80/90%، وحالة الضغط.
--  • الضغط (VACUUM FULL) لا يُنفَّذ داخل الدوال؛ يُجدوَل عبر pg_cron: المخطِّط الليلي 00:00 UTC (03:00 بغداد) يختار الجداول المنتفخة
--    (شطب ≥ 20% ومساحة ≥ 1 MB) + ما طُلب صراحة، ويتحقق من مساحة مؤقتة كافية (حجم القاعدة + حجم الجدول ≤ 95% من الحد) وإلا يؤجّل ويبلّغ IT.
--    كل جدول وظيفة cron مؤقتة تحذف نفسها بعد التنفيذ. النتائج (قبل/بعد) في space_reclaim_log.
--  • «ضغط الآن» لـ IT: يجدول الطابور بعد دقيقة واحدة بالطريقة نفسها.

create table if not exists public.space_settings (
  id                  smallint primary key default 1 check (id = 1),
  plan                text not null default 'free' check (plan in ('free', 'pro', 'custom')),
  db_limit_bytes      bigint not null default 500 * 1024 * 1024 check (db_limit_bytes > 0),
  storage_limit_bytes bigint not null default 1024 * 1024 * 1024 check (storage_limit_bytes > 0),
  bloat_threshold_pct integer not null default 20 check (bloat_threshold_pct between 5 and 90),
  updated_by          uuid references auth.users(id),
  updated_at          timestamptz not null default now()
);
insert into public.space_settings (id) values (1) on conflict (id) do nothing;
alter table public.space_settings enable row level security;

create table if not exists public.space_reclaim_log (
  id            bigint generated by default as identity primary key,
  table_name    text not null,
  reason        text not null,                 -- 'bloat' | 'requested' | 'manual'
  status        text not null default 'queued' check (status in ('queued', 'scheduled', 'done', 'skipped', 'failed')),
  requested_by  uuid references auth.users(id),
  requested_at  timestamptz not null default now(),
  scheduled_for timestamptz,
  cron_job      text,
  before_bytes  bigint,
  after_bytes   bigint,
  finished_at   timestamptz,
  note          text
);
alter table public.space_reclaim_log enable row level security;
create index if not exists space_reclaim_log_status_idx on public.space_reclaim_log(status, table_name);
create unique index if not exists space_reclaim_log_one_open_idx on public.space_reclaim_log(table_name) where status in ('queued', 'scheduled');

do $$ begin
  begin create extension if not exists pgstattuple; exception when others then raise notice 'pgstattuple غير متاح — يُستخدم تقدير الشطب من الإحصاءات'; end;
end $$;

-- ───────────── قياس الجدول: الحجم ونسبة المساحة القابلة للاسترداد ─────────────
create or replace function app.space_table_bloat(p_table text)
returns table (total_bytes bigint, live_tup bigint, dead_tup bigint, reclaimable_pct numeric)
language plpgsql stable security definer set search_path = public, app as $$
declare v_total bigint; v_live bigint; v_dead bigint; v_pct numeric; v_free numeric; v_deadpct numeric;
begin
  select pg_total_relation_size(format('%I.%I', 'public', p_table)::regclass) into v_total;
  select coalesce(n_live_tup, 0), coalesce(n_dead_tup, 0) into v_live, v_dead from pg_stat_user_tables where schemaname = 'public' and relname = p_table;
  v_pct := case when v_live + v_dead > 0 then round(100.0 * v_dead / (v_live + v_dead), 1) else 0 end;
  if exists (select 1 from pg_extension where extname = 'pgstattuple') and v_total >= 1024 * 1024 then
    begin
      execute format('select approx_free_percent, dead_tuple_percent from pgstattuple_approx(%L)', format('public.%I', p_table)) into v_free, v_deadpct;
      v_pct := greatest(v_pct, round(coalesce(v_free, 0) + coalesce(v_deadpct, 0), 1));
    exception when others then null;
    end;
  end if;
  return query select v_total, v_live, v_dead, least(v_pct, 100);
end$$;

-- ───────────── الإعدادات ─────────────
create or replace function public.space_settings_set(p_plan text, p_db_limit_bytes bigint default null, p_storage_limit_bytes bigint default null, p_bloat_threshold_pct int default null)
returns jsonb language plpgsql volatile security definer set search_path = public, app as $$
declare v_db bigint; v_st bigint;
begin
  perform app.require_it();
  if p_plan not in ('free', 'pro', 'custom') then raise exception 'SPACE_PLAN_INVALID'; end if;
  v_db := case p_plan when 'free' then 500::bigint * 1024 * 1024 when 'pro' then 8::bigint * 1024 * 1024 * 1024 else p_db_limit_bytes end;
  v_st := case p_plan when 'free' then 1::bigint * 1024 * 1024 * 1024 when 'pro' then 100::bigint * 1024 * 1024 * 1024 else p_storage_limit_bytes end;
  if v_db is null or v_st is null then raise exception 'SPACE_LIMITS_REQUIRED'; end if;
  update public.space_settings set plan = p_plan, db_limit_bytes = v_db, storage_limit_bytes = v_st,
         bloat_threshold_pct = coalesce(p_bloat_threshold_pct, bloat_threshold_pct), updated_by = auth.uid(), updated_at = now() where id = 1;
  return public.space_overview();
end$$;

-- ───────────── اللوحة ─────────────
create or replace function public.space_overview() returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
declare s public.space_settings; v_db bigint; v_storage bigint; v_tables jsonb; v_buckets jsonb; v_reclaimable bigint; v_alerts jsonb := '[]'::jsonb;
        v_cron boolean; v_log jsonb; v_queue int; v_sched int;
begin
  perform app.require_it();
  select * into s from public.space_settings where id = 1;
  v_db := pg_database_size(current_database());
  select coalesce(sum((o.metadata ->> 'size')::bigint), 0) into v_storage from storage.objects o;
  select coalesce(jsonb_agg(jsonb_build_object('bucket', b, 'objects', n, 'bytes', bytes) order by bytes desc), '[]'::jsonb) into v_buckets
  from (select o.bucket_id b, count(*) n, coalesce(sum((o.metadata ->> 'size')::bigint), 0) bytes from storage.objects o group by o.bucket_id) x;
  select coalesce(jsonb_agg(jsonb_build_object('table', t.relname, 'bytes', m.total_bytes, 'rows', m.live_tup, 'dead_rows', m.dead_tup, 'reclaimable_pct', m.reclaimable_pct,
                                              'reclaimable_bytes', (m.total_bytes * m.reclaimable_pct / 100)::bigint) order by m.total_bytes desc), '[]'::jsonb),
         coalesce(sum((m.total_bytes * m.reclaimable_pct / 100)::bigint), 0)
    into v_tables, v_reclaimable
  from (select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' order by pg_total_relation_size(c.oid) desc limit 12) t
  cross join lateral app.space_table_bloat(t.relname) m;
  if v_db >= s.db_limit_bytes * 0.9 then v_alerts := v_alerts || jsonb_build_object('level', 'danger', 'kind', 'db', 'message', 'قاعدة البيانات تجاوزت 90% من حدّ الخطة');
  elsif v_db >= s.db_limit_bytes * 0.8 then v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'kind', 'db', 'message', 'قاعدة البيانات تجاوزت 80% من حدّ الخطة'); end if;
  if v_storage >= s.storage_limit_bytes * 0.9 then v_alerts := v_alerts || jsonb_build_object('level', 'danger', 'kind', 'storage', 'message', 'التخزين تجاوز 90% من حدّ الخطة');
  elsif v_storage >= s.storage_limit_bytes * 0.8 then v_alerts := v_alerts || jsonb_build_object('level', 'warning', 'kind', 'storage', 'message', 'التخزين تجاوز 80% من حدّ الخطة'); end if;
  v_cron := exists (select 1 from pg_extension where extname = 'pg_cron');
  select count(*) filter (where status = 'queued'), count(*) filter (where status = 'scheduled') into v_queue, v_sched from public.space_reclaim_log;
  select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'table', l.table_name, 'reason', l.reason, 'status', l.status, 'requested_at', l.requested_at, 'scheduled_for', l.scheduled_for,
                 'before_bytes', l.before_bytes, 'after_bytes', l.after_bytes, 'finished_at', l.finished_at, 'note', l.note) order by l.requested_at desc), '[]'::jsonb)
    into v_log from (select * from public.space_reclaim_log order by requested_at desc limit 30) l;
  return jsonb_build_object(
    'plan', s.plan, 'db_limit_bytes', s.db_limit_bytes, 'storage_limit_bytes', s.storage_limit_bytes, 'bloat_threshold_pct', s.bloat_threshold_pct, 'settings_updated_at', s.updated_at,
    'db_bytes', v_db, 'db_free_bytes', greatest(s.db_limit_bytes - v_db, 0), 'db_pct', round(100.0 * v_db / s.db_limit_bytes, 1),
    'db_reclaimable_bytes', v_reclaimable,
    'storage_bytes', v_storage, 'storage_free_bytes', greatest(s.storage_limit_bytes - v_storage, 0), 'storage_pct', round(100.0 * v_storage / s.storage_limit_bytes, 1),
    'buckets', v_buckets, 'tables', v_tables, 'alerts', v_alerts,
    'reclaim', jsonb_build_object('cron_available', v_cron, 'queued', v_queue, 'scheduled', v_sched, 'nightly_at', '03:00 بغداد', 'log', v_log),
    'generated_at', now());
end$$;

-- ───────────── طابور الضغط ─────────────
create or replace function app.space_reclaim_enqueue(p_tables text[], p_reason text default 'requested') returns int
language plpgsql volatile security definer set search_path = public, app as $$
declare t text; n int := 0;
begin
  foreach t in array p_tables loop
    if exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname = t and c.relkind in ('r', 'p')) then
      insert into public.space_reclaim_log (table_name, reason, requested_by) values (t, p_reason, auth.uid()) on conflict do nothing;
      if found then n := n + 1; end if;
    end if;
  end loop;
  return n;
end$$;

-- المخطِّط: يختار المنتفخ تلقائياً + المطلوب، ويجدول VACUUM FULL لكل جدول كوظيفة cron مؤقتة تبدأ من p_start (كل جدول في دقيقة تالية)
create or replace function app.space_reclaim_plan(p_start timestamptz default null) returns jsonb
language plpgsql volatile security definer set search_path = public, app as $$
declare s public.space_settings; r record; v_db bigint; v_start timestamptz; i int := 0; v_cron boolean; m record; job text; v_when timestamptz; n_sched int := 0; n_skip int := 0;
begin
  select * into s from public.space_settings where id = 1;
  v_db := pg_database_size(current_database());
  v_cron := exists (select 1 from pg_extension where extname = 'pg_cron');
  -- ① الاختيار التلقائي: جداول ≥ 1 MB بنسبة شطب ≥ العتبة
  for r in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and pg_total_relation_size(c.oid) >= 1024 * 1024 loop
    select * into m from app.space_table_bloat(r.relname);
    if m.reclaimable_pct >= s.bloat_threshold_pct and (m.total_bytes * m.reclaimable_pct / 100) >= 1024 * 1024 then
      perform app.space_reclaim_enqueue(array[r.relname], 'bloat');
    end if;
  end loop;
  v_start := coalesce(p_start, now() + interval '1 minute');
  -- ② الجدولة
  for r in select * from public.space_reclaim_log where status = 'queued' order by requested_at loop
    select * into m from app.space_table_bloat(r.table_name);
    if not v_cron then
      update public.space_reclaim_log set status = 'skipped', finished_at = now(), note = 'PG_CRON_MISSING' where id = r.id; n_skip := n_skip + 1; continue;
    end if;
    -- الأمان: الضغط ينسخ الجدول مؤقتاً — يلزم أن يبقى الإجمالي ≤ 95% من الحد
    if v_db + m.total_bytes > s.db_limit_bytes * 0.95 then
      update public.space_reclaim_log set status = 'skipped', finished_at = now(), note = 'INSUFFICIENT_HEADROOM' where id = r.id; n_skip := n_skip + 1; continue;
    end if;
    v_when := v_start + make_interval(mins => i); i := i + 1;
    job := 'space-reclaim:' || r.table_name;
    execute format('select cron.unschedule(jobid) from cron.job where jobname = %L', job);
    execute format('select cron.schedule(%L, %L, %L)', job,
                   format('%s %s * * *', extract(minute from v_when at time zone 'UTC')::int, extract(hour from v_when at time zone 'UTC')::int),
                   format('VACUUM (FULL, ANALYZE) public.%I', r.table_name));
    update public.space_reclaim_log set status = 'scheduled', scheduled_for = v_when, cron_job = job, before_bytes = m.total_bytes where id = r.id;
    n_sched := n_sched + 1;
  end loop;
  if n_skip > 0 then
    insert into public.notifications (user_id, title, body, type, link)
    select ur.user_id, 'تعذر ضغط بعض الجداول', 'أُجِّل ضغط ' || n_skip || ' جدول (مساحة مؤقتة غير كافية أو المجدول غير مفعّل) — راجع لوحة المساحة.', 'warning', '/it'
    from public.user_roles ur where ur.role in ('it_admin', 'super_admin');
  end if;
  return jsonb_build_object('scheduled', n_sched, 'skipped', n_skip, 'start', v_start);
end$$;

-- الإنهاء: بعد مرور موعد التنفيذ يُقاس الحجم الجديد وتُحذف وظيفة cron المؤقتة
create or replace function app.space_reclaim_finish() returns jsonb
language plpgsql volatile security definer set search_path = public, app as $$
declare r record; v_after bigint; n int := 0; v_ok boolean;
begin
  for r in select * from public.space_reclaim_log where status = 'scheduled' and scheduled_for < now() - interval '2 minutes' loop
    v_ok := true;
    if exists (select 1 from pg_extension where extname = 'pg_cron') then
      begin
        execute format('select coalesce((select d.status = ''succeeded'' from cron.job_run_details d join cron.job j on j.jobid = d.jobid where j.jobname = %L order by d.start_time desc limit 1), true)', r.cron_job) into v_ok;
        execute format('select cron.unschedule(jobid) from cron.job where jobname = %L', r.cron_job);
      exception when others then null;
      end;
    end if;
    select pg_total_relation_size(format('%I.%I', 'public', r.table_name)::regclass) into v_after;
    update public.space_reclaim_log set status = case when v_ok then 'done' else 'failed' end, after_bytes = v_after, finished_at = now(),
           note = case when v_ok then null else 'VACUUM_FAILED' end where id = r.id;
    n := n + 1;
  end loop;
  return jsonb_build_object('finished', n);
end$$;

-- واجهة IT
create or replace function public.space_reclaim_now(p_tables text[] default null) returns jsonb
language plpgsql volatile security definer set search_path = public, app as $$
begin
  perform app.require_it();
  if p_tables is not null then perform app.space_reclaim_enqueue(p_tables, 'manual'); end if;
  return app.space_reclaim_plan(now() + interval '1 minute');
end$$;
create or replace function public.space_reclaim_sync() returns jsonb
language plpgsql volatile security definer set search_path = public, app as $$
begin
  perform app.require_it();
  return app.space_reclaim_finish();
end$$;

-- الجدولة الليلية: التخطيط 00:00 UTC (03:00 بغداد) والإنهاء 02:00 UTC
do $$ begin
  begin create extension if not exists pg_cron; exception when others then raise notice 'pg_cron غير متاح — الضغط الليلي يتطلب تفعيله'; return; end;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname in ('space_reclaim_plan_nightly', 'space_reclaim_finish_nightly');
    perform cron.schedule('space_reclaim_plan_nightly', '0 0 * * *', $job$ select app.space_reclaim_plan(now() + interval '5 minutes') $job$);
    perform cron.schedule('space_reclaim_finish_nightly', '0 2 * * *', $job$ select app.space_reclaim_finish() $job$);
  end if;
end $$;

revoke all on function public.space_settings_set(text, bigint, bigint, int) from public, anon;
revoke all on function public.space_overview() from public, anon;
revoke all on function public.space_reclaim_now(text[]) from public, anon;
revoke all on function public.space_reclaim_sync() from public, anon;
revoke all on function app.space_reclaim_enqueue(text[], text) from public;
revoke all on function app.space_reclaim_plan(timestamptz) from public;
revoke all on function app.space_reclaim_finish() from public;
revoke all on function app.space_table_bloat(text) from public;
grant execute on function public.space_settings_set(text, bigint, bigint, int) to authenticated;
grant execute on function public.space_overview() to authenticated;
grant execute on function public.space_reclaim_now(text[]) to authenticated;
grant execute on function public.space_reclaim_sync() to authenticated;

-- ───────────── كتالوج الاحتفاظ: + space_settings, space_reclaim_log ─────────────
